INSERT INTO class_features_library
  (id, class_name, subclass_name, feature_name, level_acquired, description, usage_type, uses_per_rest, uses_count)
SELECT v.id::uuid, v.class_name, v.subclass_name, v.feature_name, v.level_acquired::integer,
       v.description, v.usage_type, v.uses_per_rest, v.uses_count::integer
FROM (VALUES
  ('ded95409-a3ca-f900-4684-96860a440055', 'Barbarian', NULL, 'Rage', 1, 'In battle, you fight with primal ferocity. On your turn, you can enter a rage as a bonus action. While raging, you gain the following benefits if you aren''t wearing heavy armor:

- You have advantage on Strength checks and Strength saving throws.

- When you make a melee weapon Attack using Strength, you gain a +2 bonus to the damage roll. This bonus increases as you level.

- You have Resistance to bludgeoning, piercing, and slashing damage.

If you are able to cast Spells, you can''t cast them or concentrate on them while raging.

Your rage lasts for 1 minute. It ends early if you are knocked Unconscious or if Your Turn ends and you haven''t attacked a hostile creature since your last turn or taken damage since then. You can also end your rage on Your Turn as a Bonus Action.

Once you have raged the maximum number of times for your barbarian level, you must finish a Long Rest before you can rage again. You may rage 2 times at 1st level, 3 at 3rd, 4 at 6th, 5 at 12th, and 6 at 17th.', 'bonus_action', 'long_rest', NULL),
  ('1ad3bfd8-d496-43dd-837d-509830a7059a', 'Barbarian', NULL, 'Unarmored Defense', 1, 'While you are not wearing any armor, your Armor Class equals 10 + your Dexterity modifier + your Constitution modifier. You can use a shield and still gain this benefit.', 'passive', NULL, NULL),
  ('df8a9553-0727-cdca-9693-039b4149f6f2', 'Barbarian', NULL, 'Danger Sense', 2, 'At 2nd level, you gain an uncanny sense of when things nearby aren''t as they should be, giving you an edge when you dodge away from danger. You have advantage on Dexterity saving throws against effects that you can see, such as traps and spells. To gain this benefit, you can''t be blinded, deafened, or incapacitated.', 'passive', NULL, NULL),
  ('159e2b5a-b4c1-9218-c29e-98a937c667ed', 'Barbarian', NULL, 'Reckless Attack', 2, 'Starting at 2nd level, you can throw aside all concern for defense to attack with fierce desperation. When you make your first attack on your turn, you can decide to attack recklessly. Doing so gives you advantage on melee weapon attack rolls using Strength during this turn, but attack rolls against you have advantage until your next turn.', 'passive', NULL, NULL),
  ('14f66967-c271-2f78-06b6-8fbeabc78459', 'Barbarian', NULL, 'Primal Path', 3, 'At 3rd level, you choose a path that shapes the nature of your rage. Choose the Path of the Berserker or the Path of the Totem Warrior, both detailed at the end of the class description. Your choice grants you features at 3rd level and again at 6th, 10th, and 14th levels.', 'passive', NULL, NULL),
  ('88c2c778-f981-0e91-be33-61f16ed34cfc', 'Barbarian', NULL, 'Ability Score Improvement', 4, 'When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature.', 'passive', NULL, NULL),
  ('d220c2ea-41da-56b6-32f6-93e50dca8de6', 'Barbarian', NULL, 'Extra Attack', 5, 'Beginning at 5th level, you can attack twice, instead of once, whenever you take the Attack action on your turn.', 'passive', NULL, NULL),
  ('a82aab33-e5d2-aef3-07cd-76f0e46bf5a2', 'Barbarian', NULL, 'Fast Movement', 5, 'Starting at 5th level, your speed increases by 10 feet while you aren''t wearing heavy armor.', 'passive', NULL, NULL),
  ('c727a03e-6ee5-d844-0408-b6a065a8fc7e', 'Barbarian', NULL, 'Feral Instinct', 7, 'By 7th level, your instincts are so honed that you have advantage on initiative rolls.

Additionally, if you are surprised at the beginning of combat and aren''t incapacitated, you can act normally on your first turn, but only if you enter your rage before doing anything else on that turn.', 'passive', NULL, NULL),
  ('6bb65ec3-ae59-7908-71b2-541a4f973b80', 'Barbarian', NULL, 'Ability Score Improvement', 8, 'When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature.', 'passive', NULL, NULL),
  ('75f5c8f3-4286-bbb0-0b4d-428ee3219b5d', 'Barbarian', NULL, 'Brutal Critical (1 die)', 9, 'Beginning at 9th level, you can roll one additional weapon damage die when determining the extra damage for a critical hit with a melee attack. This increases to two additional dice at 13th level and three additional dice at 17th level.', 'passive', NULL, NULL),
  ('a92d1d9d-e81d-278e-3ccb-6fc3c5098a8f', 'Barbarian', NULL, 'Relentless Rage', 11, 'Starting at 11th level, your rage can keep you fighting despite grievous wounds. If you drop to 0 hit points while you''re raging and don''t die outright, you can make a DC 10 Constitution saving throw. If you succeed, you drop to 1 hit point instead.

Each time you use this feature after the first, the DC increases by 5. When you finish a short or long rest, the DC resets to 10.', 'limited_use', 'short_rest', NULL),
  ('f9415b82-3fcb-991c-3ee5-333722b88adf', 'Barbarian', NULL, 'Ability Score Improvement', 12, 'When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature.', 'passive', NULL, NULL),
  ('7febe9dd-0dfd-fd9a-4540-5d999e4706dc', 'Barbarian', NULL, 'Brutal Critical (2 dice)', 13, 'Beginning at 9th level, you can roll one additional weapon damage die when determining the extra damage for a critical hit with a melee attack. This increases to two additional dice at 13th level and three additional dice at 17th level.', 'passive', NULL, NULL),
  ('ca96b6d8-8ac9-3bce-378f-ed42743e8ac1', 'Barbarian', NULL, 'Persistent Rage', 15, 'Beginning at 15th level, your rage is so fierce that it ends early only if you fall unconscious or if you choose to end it.', 'passive', NULL, NULL),
  ('4cfa0efa-aadb-97c9-8402-b940bfbacf17', 'Barbarian', NULL, 'Ability Score Improvement', 16, 'When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature.', 'passive', NULL, NULL),
  ('580a165d-e65c-3fe0-2a23-767545cfe297', 'Barbarian', NULL, 'Brutal Critical (3 dice)', 17, 'Beginning at 9th level, you can roll one additional weapon damage die when determining the extra damage for a critical hit with a melee attack. This increases to two additional dice at 13th level and three additional dice at 17th level.', 'passive', NULL, NULL),
  ('5a677a87-06ff-00f9-b40a-3284a8f9a30b', 'Barbarian', NULL, 'Indomitable Might', 18, 'Beginning at 18th level, if your total for a Strength check is less than your Strength score, you can use that score in place of the total.', 'passive', NULL, NULL),
  ('0dc43d36-9ee6-0269-a3d7-2c63544bb77d', 'Barbarian', NULL, 'Ability Score Improvement', 19, 'When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature.', 'passive', NULL, NULL),
  ('4e1296e6-9082-0c18-9a9a-b3942f21fc72', 'Barbarian', NULL, 'Primal Champion', 20, 'At 20th level, you embody the power of the wilds. Your Strength and Constitution scores increase by 4. Your maximum for those scores is now 24.', 'passive', NULL, NULL),
  ('6ead2fe5-9731-6d26-e6b4-159820949075', 'Bard', NULL, 'Bardic Inspiration (d6)', 1, 'You can inspire others through stirring words or music. To do so, you use a bonus action on your turn to choose one creature other than yourself within 60 feet of you who can hear you. That creature gains one Bardic Inspiration die, a d6. Once within the next 10 minutes, the creature can roll the die and add the number rolled to one ability check, attack roll, or saving throw it makes. The creature can wait until after it rolls the d20 before deciding to use the Bardic Inspiration die, but must decide before the GM says whether the roll succeeds or fails. Once the Bardic Inspiration die is rolled, it is lost. A creature can have only one Bardic Inspiration die at a time.

You can use this feature a number of times equal to your Charisma modifier (a minimum of once). You regain any expended uses when you finish a long rest. 

Your Bardic Inspiration die changes when you reach certain levels in this class. The die becomes a d8 at 5th level, a d10 at 10th level, and a d12 at 15th level.', 'bonus_action', 'long_rest', NULL),
  ('a2e07a19-b4ac-5fbd-fa98-51da0a05a0af', 'Bard', NULL, 'Spellcasting: Bard', 1, 'You have learned to untangle and reshape the fabric of reality in harmony with your wishes and music. Your spells are part of your vast repertoire, magic that you can tune to different situations.', 'passive', NULL, NULL),
  ('61c9daa4-3404-a6d3-347c-63848719704b', 'Bard', NULL, 'Jack of All Trades', 2, 'Starting at 2nd level, you can add half your proficiency bonus, rounded down, to any ability check you make that doesn''t already include your proficiency bonus.', 'passive', NULL, NULL),
  ('b2415e54-23da-1450-a433-7c6374d1a964', 'Bard', NULL, 'Song of Rest (d6)', 2, 'Beginning at 2nd level, you can use soothing music or oration to help revitalize your wounded allies during a short rest. If you or any friendly creatures who can hear your performance regain hit points at the end of the short rest by spending one or more Hit Dice, each of those creatures regains an extra 1d6 hit points. 

The extra hit points increase when you reach certain levels in this class: to 1d8 at 9th level, to 1d10 at 13th level, and to 1d12 at 17th level.', 'limited_use', 'short_rest', NULL),
  ('8b0eaad0-4d5b-2f9e-8a59-33f649feb771', 'Bard', NULL, 'Bard College', 3, 'At 3rd level, you delve into the advanced techniques of a bard college of your choice, such as the College of Lore. Your choice grants you features at 3rd level and again at 6th and 14th level.', 'passive', NULL, NULL),
  ('1bc6fcd1-998b-ed4f-819c-ca9fb4a69d32', 'Bard', NULL, 'Expertise', 3, 'At 3rd level, choose two of your skill proficiencies. Your proficiency bonus is doubled for any ability check you make that uses either of the chosen proficiencies. At 10th level, you can choose another two skill proficiencies to gain this benefit.', 'passive', NULL, NULL),
  ('b58c7d4c-496c-09ff-3de6-41d2d0db916b', 'Bard', NULL, 'Ability Score Improvement', 4, 'When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature.', 'passive', NULL, NULL),
  ('13441da7-00a6-a652-142f-0774dda6c05b', 'Bard', NULL, 'Bardic Inspiration (d8)', 5, 'You can inspire others through stirring words or music. To do so, you use a bonus action on your turn to choose one creature other than yourself within 60 feet of you who can hear you. That creature gains one Bardic Inspiration die, a d6. Once within the next 10 minutes, the creature can roll the die and add the number rolled to one ability check, attack roll, or saving throw it makes. The creature can wait until after it rolls the d20 before deciding to use the Bardic Inspiration die, but must decide before the GM says whether the roll succeeds or fails. Once the Bardic Inspiration die is rolled, it is lost. A creature can have only one Bardic Inspiration die at a time.

You can use this feature a number of times equal to your Charisma modifier (a minimum of once). You regain any expended uses when you finish a long rest. 

Your Bardic Inspiration die changes when you reach certain levels in this class. The die becomes a d8 at 5th level, a d10 at 10th level, and a d12 at 15th level.', 'bonus_action', 'long_rest', NULL),
  ('2474d130-a6dc-75d5-4596-e802f3b97306', 'Bard', NULL, 'Font of Inspiration', 5, 'Beginning when you reach 5th level, you regain all of your expended uses of Bardic Inspiration when you finish a short or long rest.', 'limited_use', 'short_rest', NULL),
  ('ad451f41-0f78-db75-ea79-09b959848e4b', 'Bard', NULL, 'Countercharm', 6, 'At 6th level, you gain the ability to use musical notes or words of power to disrupt mind-influencing effects. As an action, you can start a performance that lasts until the end of your next turn. During that time, you and any friendly creatures within 30 feet of you have advantage on saving throws against being frightened or charmed. A creature must be able to hear you to gain this benefit. The performance ends early if you are incapacitated or silenced or if you voluntarily end it (no action required).', 'action', NULL, NULL),
  ('25731aba-9fe8-92d6-fb10-78fe4ea04d45', 'Bard', NULL, 'Ability Score Improvement', 8, 'When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature.', 'passive', NULL, NULL),
  ('5cf57259-afe2-6132-7637-6289b47f1933', 'Bard', NULL, 'Song of Rest (d8)', 9, 'Beginning at 2nd level, you can use soothing music or oration to help revitalize your wounded allies during a short rest. If you or any friendly creatures who can hear your performance regain hit points at the end of the short rest by spending one or more Hit Dice, each of those creatures regains an extra 1d6 hit points. 

The extra hit points increase when you reach certain levels in this class: to 1d8 at 9th level, to 1d10 at 13th level, and to 1d12 at 17th level.', 'limited_use', 'short_rest', NULL),
  ('e8423361-cf63-a558-c249-d429c8cb0f56', 'Bard', NULL, 'Bardic Inspiration (d10)', 10, 'You can inspire others through stirring words or music. To do so, you use a bonus action on your turn to choose one creature other than yourself within 60 feet of you who can hear you. That creature gains one Bardic Inspiration die, a d6. Once within the next 10 minutes, the creature can roll the die and add the number rolled to one ability check, attack roll, or saving throw it makes. The creature can wait until after it rolls the d20 before deciding to use the Bardic Inspiration die, but must decide before the GM says whether the roll succeeds or fails. Once the Bardic Inspiration die is rolled, it is lost. A creature can have only one Bardic Inspiration die at a time.

