  ('f1ff6954-51f3-a271-9755-9f8a9a86b340', 'Druid', NULL, 'Ability Score Improvement', 12, 'When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature.', 'passive', NULL, NULL),
  ('0035fa6a-c86d-02b2-6a0e-2a804412306e', 'Druid', NULL, 'Ability Score Improvement', 16, 'When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature.', 'passive', NULL, NULL),
  ('0e987eb6-13ec-f0bc-e528-c97c9a58c7d5', 'Druid', NULL, 'Beast Spells', 18, 'Beginning at 18th level, you can cast many of your druid spells in any shape you assume using Wild Shape. You can perform the somatic and verbal components of a druid spell while in a beast shape, but you aren''t able to provide material components.', 'passive', NULL, NULL),
  ('ad3b5bc8-91b1-0180-f43d-fde8da391bea', 'Druid', NULL, 'Timeless Body', 18, 'Starting at 18th level, the primal magic that you wield causes you to age more slowly. For every 10 years that pass, your body ages only 1 year.', 'passive', NULL, NULL),
  ('2abb4159-dcfe-6372-f9ed-c6f3e6fae250', 'Druid', NULL, 'Ability Score Improvement', 19, 'When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature.', 'passive', NULL, NULL),
  ('303ff02f-c042-c741-c04f-738234c2957c', 'Druid', NULL, 'Archdruid', 20, 'At 20th level, you can use your Wild Shape an unlimited number of times.

Additionally, you can ignore the verbal and somatic components of your druid spells, as well as any material components that lack a cost and aren''t consumed by a spell. You gain this benefit in both your normal shape and your beast shape from Wild Shape.', 'passive', NULL, NULL),
  ('a584b9d4-38c4-a0fd-274c-88cdc36de138', 'Fighter', NULL, 'Fighting Style', 1, 'You adopt a particular style of fighting as your specialty. Choose one of the following options. You can''t take a Fighting Style option more than once, even if you later get to choose again.', 'passive', NULL, NULL),
  ('a43cba29-7da0-5840-c801-28b7ddb889de', 'Fighter', NULL, 'Second Wind', 1, 'You have a limited well of stamina that you can draw on to protect yourself from harm. On your turn, you can use a bonus action to regain hit points equal to 1d10 + your fighter level. Once you use this feature, you must finish a short or long rest before you can use it again.', 'bonus_action', 'short_rest', NULL),
  ('06828104-d03c-924d-0c13-50d7af60abf8', 'Fighter', NULL, 'Action Surge (1 use)', 2, 'Starting at 2nd level, you can push yourself beyond your normal limits for a moment. On your turn, you can take one additional action on top of your regular action and a possible bonus action.

Once you use this feature, you must finish a short or long rest before you can use it again. Starting at 17th level, you can use it twice before a rest, but only once on the same turn.', 'action', 'short_rest', 1),
  ('e448c2ac-e518-5503-e6a6-fed713506678', 'Fighter', NULL, 'Martial Archetype', 3, 'At 3rd level, you choose an archetype that you strive to emulate in your combat styles and techniques, such as Champion. The archetype you choose grants you features at 3rd level and again at 7th, 10th, 15th, and 18th level.', 'passive', NULL, NULL),
  ('1fd90528-8ece-ee04-c38e-e686a2267793', 'Fighter', NULL, 'Ability Score Improvement', 4, 'When you reach 4th level, and again at 6th, 8th, 12th, 14th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature.', 'passive', NULL, NULL),
  ('ed2a57c3-2408-764b-8087-63cd1e1b919e', 'Fighter', NULL, 'Extra Attack', 5, 'Beginning at 5th level, you can attack twice, instead of once, whenever you take the Attack action on your turn. The number of attacks increases to three when you reach 11th level in this class and to four when you reach 20th level in this class.', 'passive', NULL, NULL),
  ('7e1ea923-0127-153c-4b20-ac4c3b14c7c6', 'Fighter', NULL, 'Ability Score Improvement', 6, 'When you reach 4th level, and again at 6th, 8th, 12th, 14th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature.', 'passive', NULL, NULL),
  ('83702b1f-488f-4560-672b-27b3409f27ce', 'Fighter', NULL, 'Ability Score Improvement', 8, 'When you reach 4th level, and again at 6th, 8th, 12th, 14th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature.', 'passive', NULL, NULL),
  ('1b63f9f8-89bf-a0ff-c571-58e1e5b39f84', 'Fighter', NULL, 'Indomitable (1 use)', 9, 'Beginning at 9th level, you can reroll a saving throw that you fail. If you do so, you must use the new roll, and you can''t use this feature again until you finish a long rest. You can use this feature twice between long rests starting at 13th level and three times between long rests starting at 17th level.', 'limited_use', 'long_rest', 1),
  ('29d41ad4-6ad0-3fe2-2bf1-a08f2bdf036e', 'Fighter', NULL, 'Extra Attack (2)', 11, 'Beginning at 5th level, you can attack twice, instead of once, whenever you take the Attack action on your turn. The number of attacks increases to three when you reach 11th level in this class and to four when you reach 20th level in this class.', 'passive', NULL, NULL),
  ('81293bce-23a1-db56-8874-b3066e4ec214', 'Fighter', NULL, 'Ability Score Improvement', 12, 'When you reach 4th level, and again at 6th, 8th, 12th, 14th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature.', 'passive', NULL, NULL),
  ('f03a1cb4-caf1-8c50-87c5-c44b5a1fbfd6', 'Fighter', NULL, 'Indomitable (2 uses)', 13, 'Beginning at 9th level, you can reroll a saving throw that you fail. If you do so, you must use the new roll, and you can''t use this feature again until you finish a long rest. You can use this feature twice between long rests starting at 13th level and three times between long rests starting at 17th level.', 'limited_use', 'long_rest', 2),
  ('058c93df-410e-605a-303f-45333cefc23d', 'Fighter', NULL, 'Ability Score Improvement', 14, 'When you reach 4th level, and again at 6th, 8th, 12th, 14th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature.', 'passive', NULL, NULL),
  ('c9afd90f-2e07-c7b9-d7df-604401c0dac7', 'Fighter', NULL, 'Ability Score Improvement', 16, 'When you reach 4th level, and again at 6th, 8th, 12th, 14th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature.', 'passive', NULL, NULL),
  ('29da4667-002a-068d-2034-39018d39b623', 'Fighter', NULL, 'Action Surge (2 uses)', 17, 'Starting at 2nd level, you can push yourself beyond your normal limits for a moment. On your turn, you can take one additional action on top of your regular action and a possible bonus action.

Once you use this feature, you must finish a short or long rest before you can use it again. Starting at 17th level, you can use it twice before a rest, but only once on the same turn.', 'action', 'short_rest', 2),
  ('cd793c55-8a32-a3b5-315d-4243a7b16e59', 'Fighter', NULL, 'Indomitable (3 uses)', 17, 'Beginning at 9th level, you can reroll a saving throw that you fail. If you do so, you must use the new roll, and you can''t use this feature again until you finish a long rest. You can use this feature twice between long rests starting at 13th level and three times between long rests starting at 17th level.', 'limited_use', 'long_rest', 3),
  ('be2ff8d6-5001-a436-3ab2-008d1fb59731', 'Fighter', NULL, 'Ability Score Improvement', 19, 'When you reach 4th level, and again at 6th, 8th, 12th, 14th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature.', 'passive', NULL, NULL),
  ('93253bb3-6446-3eed-4e7d-934276e7599e', 'Fighter', NULL, 'Extra Attack (3)', 20, 'Beginning at 5th level, you can attack twice, instead of once, whenever you take the Attack action on your turn. The number of attacks increases to three when you reach 11th level in this class and to four when you reach 20th level in this class.', 'passive', NULL, NULL),
  ('5d03c304-3946-06a9-5672-c5508cfbe8d1', 'Monk', NULL, 'Martial Arts', 1, 'At 1st level, your practice of martial arts gives you mastery of combat styles that use unarmed strikes and monk weapons, which are shortswords and any simple melee weapons that don''t have the two- handed or heavy property.

You gain the following benefits while you are unarmed or wielding only monk weapons and you aren''t wearing armor or wielding a shield:

- You can use Dexterity instead of Strength for the attack and damage rolls of your unarmed strikes and monk weapons.

- You can roll a d4 in place of the normal damage of your unarmed strike or monk weapon. This die changes as you gain monk levels, as shown in the Martial Arts column of Table: The Monk.

- When you use the Attack action with an unarmed strike or a monk weapon on your turn, you can make one unarmed strike as a bonus action. For example, if you take the Attack action and attack with a quarterstaff, you can also make an unarmed strike as a bonus action, assuming you haven''t already taken a bonus action this turn.

Certain monasteries use specialized forms of the monk weapons. For example, you might use a club that is two lengths of wood connected by a short chain (called a nunchaku) or a sickle with a shorter, straighter blade (called a kama). Whatever name you use for a monk weapon, you can use the game statistics provided for the weapon.', 'passive', NULL, NULL),
  ('e0f14c0d-837d-adce-2f96-0f9fac43bb27', 'Monk', NULL, 'Unarmored Defense', 1, 'Beginning at 1st level, while you are wearing no armor and not wielding a shield, your AC equals 10 + your Dexterity modifier + your Wisdom modifier.', 'passive', NULL, NULL),
  ('637c7ac9-b380-abaa-0fb0-a47ef34cb8e2', 'Monk', NULL, 'Flurry of Blows', 2, 'Immediately after you take the Attack action on your turn, you can spend 1 ki point to make two unarmed strikes as a bonus action.', 'bonus_action', NULL, NULL),
  ('b65a92c4-2cfc-325c-4d78-c7555e970941', 'Monk', NULL, 'Ki', 2, 'Starting at 2nd level, your training allows you to harness the mystic energy of ki. Your access to this energy is represented by a number of ki points. Your monk level determines the number of points you have, as shown in the Ki Points column of Table: The Monk.

You can spend these points to fuel various ki features. You start knowing three such features: Flurry of Blows, Patient Defense, and Step of the Wind. You learn more ki features as you gain levels in this class.

When you spend a ki point, it is unavailable until you finish a short or long rest, at the end of which you draw all of your expended ki back into yourself. You must spend at least 30 minutes of the rest meditating to regain your ki points.

Some of your ki features require your target to make a saving throw to resist the feature''s effects. The saving throw DC is calculated as follows:

Ki save DC = 8 + your proficiency bonus + your Wisdom modifier', 'limited_use', 'short_rest', NULL),
  ('3b85f6c0-29b9-6202-842e-842f286086d6', 'Monk', NULL, 'Patient Defense', 2, 'You can spend 1 ki point to take the Dodge action as a bonus action on your turn.', 'bonus_action', NULL, NULL),
  ('3721da61-ff06-9e0c-8fd8-61eae88bc065', 'Monk', NULL, 'Step of the Wind', 2, 'You can spend 1 ki point to take the Disengage or Dash action as a bonus action on your turn, and your jump distance is doubled for the turn.', 'bonus_action', NULL, NULL),
  ('dd99b87d-1bf3-8820-14d9-f63c7a8dda2a', 'Monk', NULL, 'Unarmored Movement', 2, 'Starting at 2nd level, your speed increases by 10 feet while you are not wearing armor or wielding a shield. This bonus increases when you reach certain monk levels, as shown in Table: The Monk.

At 9th level, you gain the ability to move along vertical surfaces and across liquids on your turn without falling during the move.', 'passive', NULL, NULL),
  ('880e022b-29cb-e2fb-17a0-a0b9d31da5e1', 'Monk', NULL, 'Deflect Missiles', 3, 'Starting at 3rd level, you can use your reaction to deflect or catch the missile when you are hit by a ranged weapon attack. When you do so, the damage you take from the attack is reduced by 1d10 + your Dexterity modifier + your monk level.

If you reduce the damage to 0, you can catch the missile if it is small enough for you to hold in one hand and you have at least one hand free. If you catch a missile in this way, you can spend 1 ki point to make a ranged attack with the weapon or piece of ammunition you just caught, as part of the same reaction. You make this attack with proficiency, regardless of your weapon proficiencies, and the missile counts as a monk weapon for the attack, which has a normal range of 20 feet and a long range of 60 feet.', 'reaction', NULL, NULL),
  ('402270cc-2a44-8a5b-3ec0-95643f165fb3', 'Monk', NULL, 'Monastic Tradition', 3, 'When you reach 3rd level, you commit yourself to a monastic tradition, such as the Way of the Open Hand. Your tradition grants you features at 3rd level and again at 6th, 11th, and 17th level.', 'passive', NULL, NULL),
  ('7699d66e-73ab-7850-cb3a-a7aa673e9f67', 'Monk', NULL, 'Ability Score Improvement', 4, 'When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature.', 'passive', NULL, NULL),
  ('00ceae81-4150-81fc-ad5c-c5d0f136d475', 'Monk', NULL, 'Slow Fall', 4, 'Beginning at 4th level, you can use your reaction when you fall to reduce any falling damage you take by an amount equal to five times your monk level.', 'reaction', NULL, NULL),
  ('5983af51-f9e0-26dd-c9ce-13fa4e1bb0e2', 'Monk', NULL, 'Extra Attack', 5, 'Beginning at 5th level, you can attack twice, instead of once, whenever you take the Attack action on your turn.', 'passive', NULL, NULL),
  ('c4ae8765-5fa6-504e-6bc5-83905e5c55a1', 'Monk', NULL, 'Stunning Strike', 5, 'Starting at 5th level, you can interfere with the flow of ki in an opponent''s body. When you hit another creature with a melee weapon attack, you can spend 1 ki point to attempt a stunning strike. The target must succeed on a Constitution saving throw or be stunned until the end of your next turn.', 'limited_use', NULL, NULL),
  ('3e269d9b-7c62-9934-5ce0-8ae2438f7f7c', 'Monk', NULL, 'Ki Empowered Strikes', 6, 'Starting at 6th level, your unarmed strikes count as magical for the purpose of overcoming resistance and immunity to nonmagical attacks and damage.', 'passive', NULL, NULL),
  ('5459c809-edb1-f06a-2b78-f052b0824e6c', 'Monk', NULL, 'Evasion', 7, 'At 7th level, your instinctive agility lets you dodge out of the way of certain area effects, such as a blue dragon''s lightning breath or a fireball spell. When you are subjected to an effect that allows you to make a Dexterity saving throw to take only half damage, you instead take no damage if you succeed on the saving throw, and only half damage if you fail.', 'passive', NULL, NULL),
  ('2f449e6d-08e4-c056-d0dc-af5b67789132', 'Monk', NULL, 'Stillness of Mind', 7, 'Starting at 7th level, you can use your action to end one effect on yourself that is causing you to be charmed or frightened.', 'action', NULL, NULL),
  ('ff9da41a-4819-b6b0-3df2-49ce3eb52b9a', 'Monk', NULL, 'Ability Score Improvement', 8, 'When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature.', 'passive', NULL, NULL),
  ('80d020ce-9f55-b0fa-5b83-68fbdc347f38', 'Monk', NULL, 'Unarmored Movement', 9, 'Starting at 2nd level, your speed increases by 10 feet while you are not wearing armor or wielding a shield. This bonus increases when you reach certain monk levels, as shown in Table: The Monk.

At 9th level, you gain the ability to move along vertical surfaces and across liquids on your turn without falling during the move.', 'passive', NULL, NULL),
  ('76a566bc-22e7-ac50-7be3-216756550e70', 'Monk', NULL, 'Purity of Body', 10, 'At 10th level, your mastery of the ki flowing through you makes you immune to disease and poison.', 'passive', NULL, NULL),
  ('25842de7-9184-fb8e-e7a8-86975a1e2d51', 'Monk', NULL, 'Ability Score Improvement', 12, 'When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature.', 'passive', NULL, NULL),
  ('2f7f25a4-fd25-671c-f2d3-15756bb536c5', 'Monk', NULL, 'Tongue of the Sun and Moon', 13, 'Starting at 13th level, you learn to touch the ki of other minds so that you understand all spoken languages. Moreover, any creature that can understand a language can understand what you say.', 'passive', NULL, NULL),
  ('4a539abb-b3e5-e9f3-2f5a-ff92589115ff', 'Monk', NULL, 'Diamond Soul', 14, 'Beginning at 14th level, your mastery of ki grants you proficiency in all saving throws.

Additionally, whenever you make a saving throw and fail, you can spend 1 ki point to reroll it and take the second result.', 'passive', NULL, NULL),
  ('2a8861d8-5640-fdd9-023d-7b668a4ad741', 'Monk', NULL, 'Timeless Body', 15, 'At 15th level, your ki sustains you so that you suffer none of the frailty of old age, and you can''t be aged magically. You can still die of old age, however. In addition, you no longer need food or water.', 'passive', NULL, NULL),
  ('1cdeccd3-dc5f-a416-9d9e-e19c5229f4e5', 'Monk', NULL, 'Ability Score Improvement', 16, 'When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature.', 'passive', NULL, NULL),
  ('650c8616-00e7-c798-6c23-5346e2fb3117', 'Monk', NULL, 'Empty Body', 18, 'Beginning at 18th level, you can use your action to spend 4 ki points to become invisible for 1 minute. During that time, you also have resistance to all damage but force damage.

Additionally, you can spend 8 ki points to cast the astral projection spell, without needing material components. When you do so, you can''t take any other creatures with you.', 'action', NULL, NULL),
  ('192714dd-0fa9-9b58-94f5-4acd89a3acee', 'Monk', NULL, 'Ability Score Improvement', 19, 'When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature.', 'passive', NULL, NULL),
  ('c533102d-ca42-f790-59df-176341f77ba6', 'Monk', NULL, 'Perfect Self', 20, 'At 20th level, when you roll for initiative and have no ki points remaining, you regain 4 ki points.', 'passive', NULL, NULL),
  ('b2c18f29-1ba6-c07c-1a8d-29bd10d257af', 'Paladin', NULL, 'Divine Sense', 1, 'The presence of strong evil registers on your senses like a noxious odor, and powerful good rings like heavenly music in your ears. As an action, you can open your awareness to detect such forces. Until the end of your next turn, you know the location of any celestial, fiend, or undead within 60 feet of you that is not behind total cover. You know the type (celestial, fiend, or undead) of any being whose presence you sense, but not its identity. Within the same radius, you also detect the presence of any place or object that has been consecrated or desecrated, as with the hallow spell.

You can use this feature a number of times equal to 1 + your Charisma modifier. When you finish a long rest, you regain all expended uses.', 'action', 'long_rest', NULL),
  ('81fdce6f-51d7-64c9-1022-ab70471289b8', 'Paladin', NULL, 'Lay on Hands', 1, 'Your blessed touch can heal wounds. You have a pool of healing power that replenishes when you take a long rest. With that pool, you can restore a total number of hit points equal to your paladin level x 5.

As an action, you can touch a creature and draw power from the pool to restore a number of hit points to that creature, up to the maximum amount remaining in your pool.

Alternatively, you can expend 5 hit points from your pool of healing to cure the target of one disease or neutralize one poison affecting it. You can cure multiple diseases and neutralize multiple poisons with a single use of Lay on Hands, expending hit points separately for each one.

This feature has no effect on undead and constructs.', 'action', 'long_rest', NULL),
  ('2dc1ef3c-7d13-ece2-c258-58faf2cae4e5', 'Paladin', NULL, 'Divine Smite', 2, 'Starting at 2nd level, when you hit a creature with a melee weapon attack, you can expend one spell slot to deal radiant damage to the target, in addition to the weapon''s damage. The extra damage is 2d8 for a 1st-level spell slot, plus 1d8 for each spell level higher than 1st, to a maximum of 5d8. The damage increases by 1d8 if the target is an undead or a fiend.', 'limited_use', NULL, NULL),
  ('b4efefd8-8ad8-2fc9-2daa-59aadc3d0eb7', 'Paladin', NULL, 'Fighting Style', 2, 'At 2nd level, you adopt a style of fighting as your specialty. Choose one of the following options. You can''t take a Fighting Style option more than once, even if you later get to choose again.', 'passive', NULL, NULL),
  ('3fab48d9-b7d6-ad84-0be2-f65f45da95f0', 'Paladin', NULL, 'Spellcasting: Paladin', 2, 'By 2nd level, you have learned to draw on divine magic through meditation and prayer to cast spells as a cleric does.', 'passive', NULL, NULL),
  ('1e7c730c-196b-f27e-7537-de2e2d6e9ec5', 'Paladin', NULL, 'Channel Divinity', 3, 'Your oath allows you to channel divine energy to fuel magical effects. Each Channel Divinity option provided by your oath explains how to use it.

When you use your Channel Divinity, you choose which option to use. You must then finish a short or long rest to use your Channel Divinity again.

Some Channel Divinity effects require saving throws. When you use such an effect from this class, the DC equals your paladin spell save DC.', 'limited_use', 'short_rest', NULL),
  ('7a5dde36-2725-8a99-4530-1ff2e76fd848', 'Paladin', NULL, 'Divine Health', 3, 'By 3rd level, the divine magic flowing through you makes you immune to disease.', 'passive', NULL, NULL),
  ('44d782ae-529a-edab-7d51-7c92df438e2d', 'Paladin', NULL, 'Oath Spells', 3, 'Each oath has a list of associated spells. You gain access to these spells at the levels specified in the oath description. Once you gain access to an oath spell, you always have it prepared. Oath spells don''t count against the number of spells you can prepare each day.

If you gain an oath spell that doesn''t appear on the paladin spell list, the spell is nonetheless a paladin spell for you.', 'passive', NULL, NULL),
  ('e48f1bb5-ba74-8f4a-bf86-e745ee3d3207', 'Paladin', NULL, 'Sacred Oath', 3, 'When you reach 3rd level, you swear the oath that binds you as a paladin forever. Up to this time you have been in a preparatory stage, committed to the path but not yet sworn to it. Now you choose an oath, such as the Oath of Devotion.

Your choice grants you features at 3rd level and again at 7th, 15th, and 20th level. Those features include oath spells and the Channel Divinity feature.', 'passive', NULL, NULL),
  ('c3f80008-0a40-54e3-e75e-a11b8d1927d5', 'Paladin', NULL, 'Ability Score Improvement', 4, 'When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature.', 'passive', NULL, NULL),
  ('f17fa3e9-767d-0d48-0d40-28262c2a624b', 'Paladin', NULL, 'Extra Attack', 5, 'Beginning at 5th level, you can attack twice, instead of once, whenever you take the Attack action on your turn.', 'passive', NULL, NULL),
  ('236fd880-de1d-62e7-73f7-7832cd93dbb2', 'Paladin', NULL, 'Aura of Protection', 6, 'Starting at 6th level, whenever you or a friendly creature within 10 feet of you must make a saving throw, the creature gains a bonus to the saving throw equal to your Charisma modifier (with a minimum bonus of +1). You must be conscious to grant this bonus.

At 18th level, the range of this aura increases to 30 feet.', 'passive', NULL, NULL),
  ('4f1e618f-8e52-21cb-c435-1b53c7554935', 'Paladin', NULL, 'Ability Score Improvement', 8, 'When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature.', 'passive', NULL, NULL),
  ('038103a0-002f-8374-6c62-58bb0da6285d', 'Paladin', NULL, 'Aura of Courage', 10, 'Starting at 10th level, you and friendly creatures within 10 feet of you can''t be frightened while you are conscious.

At 18th level, the range of this aura increases to 30 feet.', 'passive', NULL, NULL),
  ('6378d32d-b413-89fd-748d-0b51bc9f2c52', 'Paladin', NULL, 'Improved Divine Smite', 11, 'By 11th level, you are so suffused with righteous might that all your melee weapon strikes carry divine power with them. Whenever you hit a creature with a melee weapon, the creature takes an extra 1d8 radiant damage. If you also use your Divine Smite with an attack, you add this damage to the extra damage of your Divine Smite.', 'passive', NULL, NULL),
  ('1154ad26-d55b-407b-61b5-9c38a52fe04a', 'Paladin', NULL, 'Ability Score Improvement', 12, 'When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature.', 'passive', NULL, NULL),
  ('95ab4d3d-e92e-4048-60e4-785c05e38172', 'Paladin', NULL, 'Cleansing Touch', 14, 'Beginning at 14th level, you can use your action to end one spell on yourself or on one willing creature that you touch.

You can use this feature a number of times equal to your Charisma modifier (a minimum of once). You regain expended uses when you finish a long rest.', 'action', 'long_rest', NULL),
  ('cd649846-11db-ae94-7687-76c7b780ee54', 'Paladin', NULL, 'Ability Score Improvement', 16, 'When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature.', 'passive', NULL, NULL),
  ('ed9aea62-777c-7db1-a4ee-24d7bdb6bc7f', 'Paladin', NULL, 'Aura improvements', 18, 'At 18th level, the range of your auras increase to 30 feet.', 'passive', NULL, NULL),
  ('cdab9bd3-db42-7b6d-2029-2b43a4c46172', 'Paladin', NULL, 'Ability Score Improvement', 19, 'When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature.', 'passive', NULL, NULL),
  ('49900f8f-a837-0860-c5a1-64ad78eafdcc', 'Ranger', NULL, 'Favored Enemy (1 type)', 1, 'Beginning at 1st level, you have significant experience studying, tracking, hunting, and even talking to a certain type of enemy.

Choose a type of favored enemy: aberrations, beasts, celestials, constructs, dragons, elementals, fey, fiends, giants, monstrosities, oozes, plants, or undead. Alternatively, you can select two races of humanoid (such as gnolls and orcs) as favored enemies.

You have advantage on Wisdom (Survival) checks to track your favored enemies, as well as on Intelligence checks to recall information about them.

When you gain this feature, you also learn one language of your choice that is spoken by your favored enemies, if they speak one at all.

You choose one additional favored enemy, as well as an associated language, at 6th and 14th level. As you gain levels, your choices should reflect the types of monsters you have encountered on your adventures.', 'passive', NULL, NULL),
  ('a66779ad-62b4-6017-58ef-9035c8012a36', 'Ranger', NULL, 'Natural Explorer (1 terrain type)', 1, 'You are particularly familiar with one type of natural environment and are adept at traveling and surviving in such regions. Choose one type of favored terrain: arctic, coast, desert, forest, grassland, mountain, or swamp. When you make an Intelligence or Wisdom check related to your favored terrain, your proficiency bonus is doubled if you are using a skill that you''re proficient in.

While traveling for an hour or more in your favored terrain, you gain the following benefits:

- Difficult terrain doesn''t slow your group''s travel.

- Your group can''t become lost except by magical means.

- Even when you are engaged in another activity while traveling (such as foraging, navigating, or tracking), you remain alert to danger.

- If you are traveling alone, you can move stealthily at a normal pace.

- When you forage, you find twice as much food as you normally would.

- While tracking other creatures, you also learn their exact number, their sizes, and how long ago they passed through the area.

You choose additional favored terrain types at 6th and 10th level.', 'passive', NULL, NULL),
  ('ceaa5b73-23a1-3d0b-1c50-7ab0fb059c0a', 'Ranger', NULL, 'Fighting Style', 2, 'At 2nd level, you adopt a particular style of fighting as your specialty. Choose one of the following options. You can''t take a Fighting Style option more than once, even if you later get to choose again.', 'passive', NULL, NULL),
  ('ce9ce8af-1ab3-86b9-7d11-2592faac940b', 'Ranger', NULL, 'Spellcasting: Ranger', 2, 'By the time you reach 2nd level, you have learned to use the magical essence of nature to cast spells, much as a druid does.', 'passive', NULL, NULL),
  ('ec13ba35-6b90-8639-5656-d9abfe51dc72', 'Ranger', NULL, 'Primeval Awareness', 3, 'Beginning at 3rd level, you can use your action and expend one ranger spell slot to focus your awareness on the region around you. For 1 minute per level of the spell slot you expend, you can sense whether the following types of creatures are present within 1 mile of you (or within up to 6 miles if you are in your favored terrain): aberrations, celestials, dragons, elementals, fey, fiends, and undead. This feature doesn''t reveal the creatures'' location or number.', 'action', NULL, NULL),
  ('db3c419b-1594-3b96-3739-46857e39a99d', 'Ranger', NULL, 'Ranger Archetype', 3, 'At 3rd level, you choose an archetype that you strive to emulate, such as the Hunter. Your choice grants you features at 3rd level and again at 7th, 11th, and 15th level.', 'passive', NULL, NULL),
  ('eb0936d1-bdff-176d-9859-a60aabb287cc', 'Ranger', NULL, 'Ability Score Improvement', 4, 'When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature.', 'passive', NULL, NULL),
  ('52b739cf-113e-04f7-6a38-bb22c740839c', 'Ranger', NULL, 'Extra Attack', 5, 'Beginning at 5th level, you can attack twice, instead of once, whenever you take the Attack action on your turn.', 'passive', NULL, NULL),
  ('6244c7ca-0340-f2e2-dc4d-4689aa0208ea', 'Ranger', NULL, 'Favored Enemy (2 types)', 6, 'Beginning at 1st level, you have significant experience studying, tracking, hunting, and even talking to a certain type of enemy.

Choose a type of favored enemy: aberrations, beasts, celestials, constructs, dragons, elementals, fey, fiends, giants, monstrosities, oozes, plants, or undead. Alternatively, you can select two races of humanoid (such as gnolls and orcs) as favored enemies.

You have advantage on Wisdom (Survival) checks to track your favored enemies, as well as on Intelligence checks to recall information about them.

When you gain this feature, you also learn one language of your choice that is spoken by your favored enemies, if they speak one at all.

You choose one additional favored enemy, as well as an associated language, at 6th and 14th level. As you gain levels, your choices should reflect the types of monsters you have encountered on your adventures.', 'passive', NULL, NULL),
  ('1b21c780-bfae-486a-1014-63f1f1c79859', 'Ranger', NULL, 'Natural Explorer (2 terrain types)', 6, 'You are particularly familiar with one type of natural environment and are adept at traveling and surviving in such regions. Choose one type of favored terrain: arctic, coast, desert, forest, grassland, mountain, or swamp. When you make an Intelligence or Wisdom check related to your favored terrain, your proficiency bonus is doubled if you are using a skill that you''re proficient in.

While traveling for an hour or more in your favored terrain, you gain the following benefits:

- Difficult terrain doesn''t slow your group''s travel.

- Your group can''t become lost except by magical means.

- Even when you are engaged in another activity while traveling (such as foraging, navigating, or tracking), you remain alert to danger.

- If you are traveling alone, you can move stealthily at a normal pace.

- When you forage, you find twice as much food as you normally would.

- While tracking other creatures, you also learn their exact number, their sizes, and how long ago they passed through the area.

You choose additional favored terrain types at 6th and 10th level.', 'passive', NULL, NULL),
  ('dffb804f-8da3-3266-46b2-7878de7838aa', 'Ranger', NULL, 'Ability Score Improvement', 8, 'When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature.', 'passive', NULL, NULL),
  ('0f604c18-5972-9a68-7fe9-7c18e9ae4e51', 'Ranger', NULL, 'Land''s Stride', 8, 'Starting at 8th level, moving through nonmagical difficult terrain costs you no extra movement. You can also pass through nonmagical plants without being slowed by them and without taking damage from them if they have thorns, spines, or a similar hazard.

In addition, you have advantage on saving throws against plants that are magically created or manipulated to impede movement, such those created by the entangle spell.', 'passive', NULL, NULL),
  ('86c94164-2369-b1be-dc82-ec301b626bd9', 'Ranger', NULL, 'Hide in Plain Sight', 10, 'Starting at 10th level, you can spend 1 minute creating camouflage for yourself. You must have access to fresh mud, dirt, plants, soot, and other naturally occurring materials with which to create your camouflage.

Once you are camouflaged in this way, you can try to hide by pressing yourself up against a solid surface, such as a tree or wall, that is at least as tall and wide as you are. You gain a +10 bonus to Dexterity (Stealth) checks as long as you remain there without moving or taking actions. Once you move or take an action or a reaction, you must camouflage yourself again to gain this benefit.', 'reaction', NULL, NULL),
  ('d8c8ae20-b57e-9588-535f-a5dc5b6802fa', 'Ranger', NULL, 'Natural Explorer (3 terrain types)', 10, 'You are particularly familiar with one type of natural environment and are adept at traveling and surviving in such regions. Choose one type of favored terrain: arctic, coast, desert, forest, grassland, mountain, or swamp. When you make an Intelligence or Wisdom check related to your favored terrain, your proficiency bonus is doubled if you are using a skill that you''re proficient in.

While traveling for an hour or more in your favored terrain, you gain the following benefits:

- Difficult terrain doesn''t slow your group''s travel.

- Your group can''t become lost except by magical means.

- Even when you are engaged in another activity while traveling (such as foraging, navigating, or tracking), you remain alert to danger.

- If you are traveling alone, you can move stealthily at a normal pace.

- When you forage, you find twice as much food as you normally would.

- While tracking other creatures, you also learn their exact number, their sizes, and how long ago they passed through the area.

You choose additional favored terrain types at 6th and 10th level.', 'passive', NULL, NULL),
  ('1aecc87c-3049-1891-6846-eecb3849aef5', 'Ranger', NULL, 'Ability Score Improvement', 12, 'When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature.', 'passive', NULL, NULL),
  ('75467ff5-8ed1-08e4-7178-10a2a8e48c64', 'Ranger', NULL, 'Favored Enemy (3 enemies)', 14, 'Beginning at 1st level, you have significant experience studying, tracking, hunting, and even talking to a certain type of enemy.

Choose a type of favored enemy: aberrations, beasts, celestials, constructs, dragons, elementals, fey, fiends, giants, monstrosities, oozes, plants, or undead. Alternatively, you can select two races of humanoid (such as gnolls and orcs) as favored enemies.

You have advantage on Wisdom (Survival) checks to track your favored enemies, as well as on Intelligence checks to recall information about them.

When you gain this feature, you also learn one language of your choice that is spoken by your favored enemies, if they speak one at all.

You choose one additional favored enemy, as well as an associated language, at 6th and 14th level. As you gain levels, your choices should reflect the types of monsters you have encountered on your adventures.', 'passive', NULL, NULL),
  ('9b6b7f89-5d7a-edab-b0dc-eb24095b4310', 'Ranger', NULL, 'Vanish', 14, 'Starting at 14th level, you can use the Hide action as a bonus action on your turn. Also, you can''t be tracked by nonmagical means, unless you choose to leave a trail.', 'bonus_action', NULL, NULL),
  ('1662570b-fb36-a1bd-456e-1ff244900194', 'Ranger', NULL, 'Ability Score Improvement', 16, 'When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature.', 'passive', NULL, NULL),
  ('a463a81f-5c44-ce74-6b81-2fbb8ff16289', 'Ranger', NULL, 'Feral Senses', 18, 'At 18th level, you gain preternatural senses that help you fight creatures you can''t see. When you attack a creature you can''t see, your inability to see it doesn''t impose disadvantage on your attack rolls against it.

You are also aware of the location of any invisible creature within 30 feet of you, provided that the creature isn''t hidden from you and you aren''t blinded or deafened.', 'passive', NULL, NULL),
  ('6a340354-72ef-066a-db67-56a0479c0c16', 'Ranger', NULL, 'Ability Score Improvement', 19, 'When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature.', 'passive', NULL, NULL),
  ('ce5ccf3c-8a54-5b40-858e-9af9cc2c89a5', 'Ranger', NULL, 'Foe Slayer', 20, 'At 20th level, you become an unparalleled hunter of your enemies. Once on each of your turns, you can add your Wisdom modifier to the attack roll or the damage roll of an attack you make against one of your favored enemies. You can choose to use this feature before or after the roll, but before any effects of the roll are applied.', 'passive', NULL, NULL),
  ('87f17777-b675-65cd-88ee-7b16a6ad3ffe', 'Rogue', NULL, 'Expertise', 1, 'At 1st level, choose two of your skill proficiencies, or one of your skill proficiencies and your proficiency with thieves'' tools. Your proficiency bonus is doubled for any ability check you make that uses either of the chosen proficiencies.

At 6th level, you can choose two more of your proficiencies (in skills or with thieves'' tools) to gain this benefit', 'passive', NULL, NULL),
  ('68dbfdd2-1875-c042-0c2c-0b624f0e8596', 'Rogue', NULL, 'Sneak Attack', 1, 'Beginning at 1st level, you know how to strike subtly and exploit a foe''s distraction. Once per turn, you can deal an extra 1d6 damage to one creature you hit with an attack if you have advantage on the attack roll. The attack must use a finesse or a ranged weapon.

You don''t need advantage on the attack roll if another enemy of the target is within 5 feet of it, that enemy isn''t incapacitated, and you don''t have disadvantage on the attack roll.

The amount of the extra damage increases as you gain levels in this class, as shown in the Sneak Attack column of the Rogue table.', 'passive', NULL, NULL),
  ('2998647e-e562-e00a-dee2-cf8ea0e72d18', 'Rogue', NULL, 'Thieves'' Cant', 1, 'During your rogue training you learned thieves'' cant, a secret mix of dialect, jargon, and code that allows you to hide messages in seemingly normal conversation. Only another creature that knows thieves'' cant understands such messages. It takes four times longer to convey such a message than it does to speak the same idea plainly.

In addition, you understand a set of secret signs and symbols used to convey short, simple messages, such as whether an area is dangerous or the territory of a thieves'' guild, whether loot is nearby, or whether the people in an area are easy marks or will provide a safe house for thieves on the run.', 'passive', NULL, NULL),
  ('0bc2197b-3b2a-8e07-5750-f5d782abdbfa', 'Rogue', NULL, 'Cunning Action', 2, 'Starting at 2nd level, your quick thinking and agility allow you to move and act quickly. You can take a bonus action on each of your turns in combat. This action can be used only to take the Dash, Disengage, or Hide action.', 'bonus_action', NULL, NULL),
  ('46a1a3d2-d111-c88d-9c38-0438a1efe1bc', 'Rogue', NULL, 'Roguish Archetype', 3, 'At 3rd level, you choose an archetype that you emulate in the exercise of your rogue abilities, such as Thief. Additional archetypes are available in the original source material. Your archetype choice grants you features at 3rd level and then again at 9th, 13th, and 17th level.', 'passive', NULL, NULL),
  ('bc35f989-c756-786d-f1c7-64b7b80b7208', 'Rogue', NULL, 'Ability Score Improvement', 4, 'When you reach 4th level, and again at 8th, 10th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature.', 'passive', NULL, NULL),
  ('b9ce3979-d93a-3d96-eb71-b4658e920aeb', 'Rogue', NULL, 'Uncanny Dodge', 5, 'Starting at 5th level, when an attacker that you can see hits you with an attack, you can use your reaction to halve the attack''s damage against you.', 'reaction', NULL, NULL),
  ('4fd270c0-7877-aa49-ee95-09b0185b68e8', 'Rogue', NULL, 'Expertise', 6, 'At 1st level, choose two of your skill proficiencies, or one of your skill proficiencies and your proficiency with thieves'' tools. Your proficiency bonus is doubled for any ability check you make that uses either of the chosen proficiencies.

At 6th level, you can choose two more of your proficiencies (in skills or with thieves'' tools) to gain this benefit', 'passive', NULL, NULL),
  ('30e5224d-8d54-6528-a526-c86f86b349ad', 'Rogue', NULL, 'Evasion', 7, 'Beginning at 7th level, you can nimbly dodge out of the way of certain area effects, such as a red dragon''s fiery breath or an ice storm spell. When you are subjected to an effect that allows you to make a Dexterity saving throw to take only half damage, you instead take no damage if you succeed on the saving throw, and only half damage if you fail.', 'passive', NULL, NULL),
  ('a69e9008-2d89-6c94-0d97-98230edcfa9c', 'Rogue', NULL, 'Ability Score Improvement', 8, 'When you reach 4th level, and again at 8th, 10th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature.', 'passive', NULL, NULL),
  ('f656747f-7333-a314-e206-c93d66d9a4c3', 'Rogue', NULL, 'Ability Score Improvement', 10, 'When you reach 4th level, and again at 8th, 10th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature.', 'passive', NULL, NULL),
  ('ea9c8007-6763-e0ec-2622-b6b3a16fce86', 'Rogue', NULL, 'Reliable Talent', 11, 'By 11th level, you have refined your chosen skills until they approach perfection. Whenever you make an ability check that lets you add your proficiency bonus, you can treat a d20 roll of 9 or lower as a 10.', 'passive', NULL, NULL),
  ('81fbbd99-60ce-2980-051a-2ee38f87d522', 'Rogue', NULL, 'Ability Score Improvement', 12, 'When you reach 4th level, and again at 8th, 10th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature.', 'passive', NULL, NULL),
  ('18a9476f-f618-8cc0-2cb6-6acfdbbbcd72', 'Rogue', NULL, 'Blindsense', 14, 'Starting at 14th level, if you are able to hear, you are aware of the location of any hidden or invisible creature within 10 feet of you.', 'passive', NULL, NULL),
  ('eb8f7418-6354-8580-4956-c1d3a1cffeb3', 'Rogue', NULL, 'Slippery Mind', 15, 'By 15th level, you have acquired greater mental strength. You gain proficiency in Wisdom saving throws.', 'passive', NULL, NULL),
  ('8ec211c3-8bc0-a8d5-2c99-088b055d8dfb', 'Rogue', NULL, 'Ability Score Improvement', 16, 'When you reach 4th level, and again at 8th, 10th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature.', 'passive', NULL, NULL),
  ('794dcab5-3ae7-ffc4-112d-753b768355b5', 'Rogue', NULL, 'Elusive', 18, 'Beginning at 18th level, you are so evasive that attackers rarely gain the upper hand against you. No attack roll has advantage against you while you aren''t incapacitated.', 'passive', NULL, NULL),
  ('d3e6c0b6-7600-8b9e-431f-4f4f9d53792c', 'Rogue', NULL, 'Ability Score Improvement', 19, 'When you reach 4th level, and again at 8th, 10th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature.', 'passive', NULL, NULL),
  ('b228785f-3e74-9c18-f9c6-251fec824ac2', 'Rogue', NULL, 'Stroke of Luck', 20, 'At 20th level, you have an uncanny knack for succeeding when you need to. If your attack misses a target within range, you can turn the miss into a hit. Alternatively, if you fail an ability check, you can treat the d20 roll as a 20.

Once you use this feature, you can''t use it again until you finish a short or long rest.', 'limited_use', 'short_rest', NULL),
  ('edd3b810-bfa2-93af-38cc-b854ef4eba3e', 'Sorcerer', NULL, 'Sorcerous Origin', 1, 'Choose a sorcerous origin, which describes the source of your innate magical power, such as Draconic Bloodline.

Your choice grants you features when you choose it at 1st level and again at 6th, 14th, and 18th level.', 'passive', NULL, NULL),
  ('fb305946-df48-7198-2668-d5a572476e53', 'Sorcerer', NULL, 'Spellcasting: Sorcerer', 1, 'An event in your past, or in the life of a parent or ancestor, left an indelible mark on you, infusing you with arcane magic. This font of magic, whatever its origin, fuels your spells.', 'passive', NULL, NULL),
  ('0bc17230-ee18-7983-1f9f-976866b48ce8', 'Sorcerer', NULL, 'Flexible Casting: Converting Spell Slot', 2, 'As a bonus action on your turn, you can expend one spell slot and gain a number of sorcery points equal to the slot''s level..', 'bonus_action', NULL, NULL),
  ('d588aa44-b0fb-5afc-df3f-bd9acd3dd72c', 'Sorcerer', NULL, 'Flexible Casting: Creating Spell Slots', 2, 'You can transform unexpended sorcery points into one spell slot as a bonus action on your turn. The Creating Spell Slots table shows the cost of creating a spell slot of a given level. You can create spell slots no higher in level than 5th. 

Any spell slot you create with this feature vanishes when you finish a long rest.', 'bonus_action', 'long_rest', NULL),
  ('8b795ca2-61cc-ff30-1dcc-76fe8cf1c8d8', 'Sorcerer', NULL, 'Font of Magic', 2, 'At 2nd level, you tap into a deep wellspring of magic within yourself. This wellspring is represented by sorcery points, which allow you to create a variety of magical effects.

Sorcery Points

You have 2 sorcery points, and you gain more as you reach higher levels, as shown in the Sorcery Points column of the Sorcerer table. You can never have more sorcery points than shown on the table for your level. You regain all spent sorcery points when you finish a long rest.', 'limited_use', 'long_rest', NULL),
  ('4119732f-54ee-4679-7361-ab67478ebfc7', 'Sorcerer', NULL, 'Metamagic', 3, 'At 3rd level, you gain the ability to twist your spells to suit your needs. You gain two of the following Metamagic options of your choice. You gain another one at 10th and 17th level.

You can use only one Metamagic option on a spell when you cast it, unless otherwise noted.', 'limited_use', NULL, NULL),
  ('004d1102-3614-fb6b-abc3-f7ab5fc82602', 'Sorcerer', NULL, 'Ability Score Improvement', 4, 'When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature.', 'passive', NULL, NULL),
  ('f7855199-42f6-ef41-857f-d6dd9f4b9711', 'Sorcerer', NULL, 'Ability Score Improvement', 8, 'When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature.', 'passive', NULL, NULL),
  ('91690c22-b6bb-1f29-ec49-4d5f388f5221', 'Sorcerer', NULL, 'Metamagic', 10, 'At 3rd level, you gain the ability to twist your spells to suit your needs. You gain two of the following Metamagic options of your choice. You gain another one at 10th and 17th level.

You can use only one Metamagic option on a spell when you cast it, unless otherwise noted.', 'limited_use', NULL, NULL),
  ('df5a07d5-a389-7126-9f8f-a45444e229b4', 'Sorcerer', NULL, 'Ability Score Improvement', 12, 'When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature.', 'passive', NULL, NULL),
  ('89c80a3b-a029-ac86-8f59-d2ea1e26de27', 'Sorcerer', NULL, 'Ability Score Improvement', 16, 'When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature.', 'passive', NULL, NULL),
  ('fcca0e15-d027-d627-6244-626d7da4d25c', 'Sorcerer', NULL, 'Metamagic', 17, 'At 3rd level, you gain the ability to twist your spells to suit your needs. You gain two of the following Metamagic options of your choice. You gain another one at 10th and 17th level.

You can use only one Metamagic option on a spell when you cast it, unless otherwise noted.', 'limited_use', NULL, NULL),
  ('f068095e-306c-9329-6fad-49ec22971c62', 'Sorcerer', NULL, 'Ability Score Improvement', 19, 'When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature.', 'passive', NULL, NULL),
  ('6c085125-5d4c-265d-1f3b-876efc897bf7', 'Sorcerer', NULL, 'Sorcerous Restoration', 20, 'At 20th level, you regain 4 expended sorcery points whenever you finish a short rest.', 'limited_use', 'short_rest', NULL),
  ('c656a89f-fd03-d0ce-6bf3-b82466070f21', 'Warlock', NULL, 'Otherworldly Patron', 1, 'At 1st level, you have struck a bargain with an otherworldly being of your choice, such as the Fiend. Your choice grants you features at 1st level and again at 6th, 10th, and 14th level.', 'passive', NULL, NULL),
  ('f3ba863e-bd82-634b-518d-09a02a0b2364', 'Warlock', NULL, 'Pact Magic', 1, 'Your arcane research and the magic bestowed on you by your patron have given you facility with spells.', 'passive', NULL, NULL),
  ('769051be-0819-a05f-a6b8-9b06ac5e8220', 'Warlock', NULL, 'Eldritch Invocations', 2, 'In your study of occult lore, you have unearthed eldritch invocations, fragments of forbidden knowledge that imbue you with an abiding magical ability.

At 2nd level, you gain two eldritch invocations of your choice. Your invocation options are detailed at the end of the class description. When you gain certain warlock levels, you gain additional invocations of your choice, as shown in the Invocations Known column of the Warlock table.

Additionally, when you gain a level in this class, you can choose one of the invocations you know and replace it with another invocation that you could learn at that level.', 'passive', NULL, NULL),
  ('99097f74-258c-18a7-0f51-e20109838cf6', 'Warlock', NULL, 'Pact Boon', 3, 'At 3rd level, your otherworldly patron bestows a gift upon you for your loyal service. You gain one of the following features of your choice.', 'passive', NULL, NULL),
  ('f808b402-9dcd-7f89-2560-b807a085b4e5', 'Warlock', NULL, 'Ability Score Improvement', 4, 'When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature.', 'passive', NULL, NULL),
  ('61ff9f66-b432-04d4-0ebb-b83ae0e95265', 'Warlock', NULL, 'Ability Score Improvement', 8, 'When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature.', 'passive', NULL, NULL),
  ('769d551f-b805-26fe-3549-cc06d725f3f1', 'Warlock', NULL, 'Mystic Arcanum (6th level)', 11, 'At 11th level, your patron bestows upon you a magical secret called an arcanum. Choose one 6th- level spell from the warlock spell list as this arcanum.

You can cast your arcanum spell once without expending a spell slot. You must finish a long rest before you can do so again.

At higher levels, you gain more warlock spells of your choice that can be cast in this way: one 7th- level spell at 13th level, one 8th-level spell at 15th level, and one 9th-level spell at 17th level. You regain all uses of your Mystic Arcanum when you finish a long rest.', 'limited_use', 'long_rest', NULL),
  ('6c597669-47aa-6860-77a9-e3cfdad08918', 'Warlock', NULL, 'Ability Score Improvement', 12, 'When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature.', 'passive', NULL, NULL),
  ('823f89e2-d156-9384-dbdb-673d307901bc', 'Warlock', NULL, 'Mystic Arcanum (7th level)', 13, 'At 11th level, your patron bestows upon you a magical secret called an arcanum. Choose one 6th- level spell from the warlock spell list as this arcanum.

You can cast your arcanum spell once without expending a spell slot. You must finish a long rest before you can do so again.

At higher levels, you gain more warlock spells of your choice that can be cast in this way: one 7th- level spell at 13th level, one 8th-level spell at 15th level, and one 9th-level spell at 17th level. You regain all uses of your Mystic Arcanum when you finish a long rest.', 'limited_use', 'long_rest', NULL),
  ('c18ab5f5-5401-b3bf-3630-066e0997a0d3', 'Warlock', NULL, 'Mystic Arcanum (8th level)', 15, 'At 11th level, your patron bestows upon you a magical secret called an arcanum. Choose one 6th- level spell from the warlock spell list as this arcanum.

You can cast your arcanum spell once without expending a spell slot. You must finish a long rest before you can do so again.

At higher levels, you gain more warlock spells of your choice that can be cast in this way: one 7th- level spell at 13th level, one 8th-level spell at 15th level, and one 9th-level spell at 17th level. You regain all uses of your Mystic Arcanum when you finish a long rest.', 'limited_use', 'long_rest', NULL),
  ('93819be6-0ec3-1ded-ee43-2c3c996d435d', 'Warlock', NULL, 'Ability Score Improvement', 16, 'When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature.', 'passive', NULL, NULL),
  ('1b87b22e-3f77-88f4-fd41-1f8e25d3aff8', 'Warlock', NULL, 'Mystic Arcanum (9th level)', 17, 'At 11th level, your patron bestows upon you a magical secret called an arcanum. Choose one 6th- level spell from the warlock spell list as this arcanum.

You can cast your arcanum spell once without expending a spell slot. You must finish a long rest before you can do so again.

At higher levels, you gain more warlock spells of your choice that can be cast in this way: one 7th- level spell at 13th level, one 8th-level spell at 15th level, and one 9th-level spell at 17th level. You regain all uses of your Mystic Arcanum when you finish a long rest.', 'limited_use', 'long_rest', NULL),
  ('9e376098-3191-f5e0-21ba-9453033df617', 'Warlock', NULL, 'Ability Score Improvement', 19, 'When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature.', 'passive', NULL, NULL),
  ('48abfa3d-0004-beae-04e8-88e18a993cea', 'Warlock', NULL, 'Eldritch Master', 20, 'At 20th level, you can draw on your inner reserve of mystical power while entreating your patron to regain expended spell slots. You can spend 1 minute entreating your patron for aid to regain all your expended spell slots from your Pact Magic feature.

Once you regain spell slots with this feature, you must finish a long rest before you can do so again.', 'limited_use', 'long_rest', NULL),
  ('1b83c4d4-34b0-e359-07fc-a31f8a80907c', 'Wizard', NULL, 'Arcane Recovery', 1, 'You have learned to regain some of your magical energy by studying your spellbook. Once per day when you finish a short rest, you can choose expended spell slots to recover. The spell slots can have a combined level that is equal to or less than half your wizard level (rounded up), and none of the slots can be 6th level or higher.

For example, if you''re a 4th-level wizard, you can recover up to two levels worth of spell slots. You can recover either a 2nd-level spell slot or two 1st-level spell slots.', 'limited_use', 'short_rest', NULL),
  ('bd20c93c-36d2-1096-f43c-2d643079b2fb', 'Wizard', NULL, 'Spellcasting: Wizard', 1, 'As a student of arcane magic, you have a spellbook containing spells that show the first glimmerings of your true power.', 'passive', NULL, NULL),
  ('54c86be2-c954-9bf3-8760-a685d5c21166', 'Wizard', NULL, 'Arcane Tradition', 2, 'When you reach 2nd level, you choose an arcane tradition, shaping your practice of magic through one of eight schools, such as Evocation.

Your choice grants you features at 2nd level and again at 6th, 10th, and 14th level.', 'passive', NULL, NULL),
  ('7cf2c610-74b4-7c3a-de9e-4022eefa70eb', 'Wizard', NULL, 'Ability Score Improvement', 4, 'When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature.', 'passive', NULL, NULL),
  ('5e3c9a5b-25e7-6c41-39b2-4a423b23e8d4', 'Wizard', NULL, 'Ability Score Improvement', 8, 'When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature.', 'passive', NULL, NULL),
  ('ed63420b-9408-74d2-35e9-09dd9655b3f8', 'Wizard', NULL, 'Ability Score Improvement', 12, 'When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature.', 'passive', NULL, NULL),
  ('d9e30d3f-3a87-9eaa-78a6-2d0a31ad3c68', 'Wizard', NULL, 'Ability Score Improvement', 16, 'When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature.', 'passive', NULL, NULL),
  ('ca3c9e6d-ee54-8624-c915-250879819c8c', 'Wizard', NULL, 'Spell Mastery', 18, 'At 18th level, you have achieved such mastery over certain spells that you can cast them at will. Choose a 1st-level wizard spell and a 2nd-level wizard spell that are in your spellbook. You can cast those spells at their lowest level without expending a spell slot when you have them prepared. If you want to cast either spell at a higher level, you must expend a spell slot as normal.

By spending 8 hours in study, you can exchange one or both of the spells you chose for different spells of the same levels.', 'passive', NULL, NULL),
  ('26467573-bf51-cf01-5f86-8311c0df3d36', 'Wizard', NULL, 'Ability Score Improvement', 19, 'When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature.', 'passive', NULL, NULL),
  ('a945a785-1278-4730-ad39-ae1c1633264c', 'Wizard', NULL, 'Signature Spell', 20, 'When you reach 20th level, you gain mastery over two powerful spells and can cast them with little effort. Choose two 3rd-level wizard spells in your spellbook as your signature spells. You always have these spells prepared, they don''t count against the number of spells you have prepared, and you can cast each of them once at 3rd level without expending a spell slot. When you do so, you can''t do so again until you finish a short or long rest.

If you want to cast either spell at a higher level, you must expend a spell slot as normal.', 'limited_use', 'short_rest', NULL),
  ('44472931-e707-571b-a90b-bd50c1f00b86', 'Barbarian', 'Path of the Berserker', 'Frenzy', 3, 'While raging, make one melee weapon attack as a bonus action; suffer one exhaustion level when the rage ends.', 'bonus_action', NULL, NULL),
  ('1a4674ad-9fde-8741-18f7-bf9b48e0bcbc', 'Barbarian', 'Path of the Berserker', 'Mindless Rage', 6, 'You cannot be charmed or frightened while raging.', 'passive', NULL, NULL),
  ('d7217a2f-dfa9-9c2f-3bf5-705ad5785ef1', 'Barbarian', 'Path of the Berserker', 'Intimidating Presence', 10, 'Use your action to frighten a creature that can see or hear you.', 'action', NULL, NULL),
  ('5eaeb709-fa08-4900-31c9-3222db20455c', 'Barbarian', 'Path of the Berserker', 'Retaliation', 14, 'Use your reaction to make a melee weapon attack against a creature that damages you within 5 feet.', 'reaction', NULL, NULL),
  ('c3b18c1d-cbc2-660f-d6b1-c01acef32bd6', 'Bard', 'College of Lore', 'Bonus Proficiencies', 3, 'Gain proficiency with three skills of your choice.', 'passive', NULL, NULL),
  ('28a81837-a503-b609-bfea-159eb6bfe6a8', 'Bard', 'College of Lore', 'Cutting Words', 3, 'Spend Bardic Inspiration as a reaction to reduce a creature’s attack, ability check, or damage roll.', 'reaction', NULL, NULL),
  ('f141471b-9e18-e1c0-489d-b88919dbdb99', 'Bard', 'College of Lore', 'Additional Magical Secrets', 6, 'Learn two spells from any class.', 'passive', NULL, NULL),
